function validate([cells, n]) {
  if (!Array.isArray(cells) || cells.length !== 8) return 'cells must hold exactly 8 values.';
  if (cells.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  if (!Number.isInteger(n) || n < 1 || n > 1e9) return 'n is an integer from 1 to 10^9.';
  return null;
}

