function prisonAfterNDays(cells, n) {
  const seen = new Map();
  let state = cells.slice();
  let day = 0;

  while (day < n) {
    const key = state.join('');
    if (seen.has(key)) {
      const cycle = day - seen.get(key);
      day = n - ((n - day) % cycle);
      seen.clear();
      if (day === n) {
        break;
      }
    }
    seen.set(key, day);
    const next = new Array(8).fill(0);
    for (let i = 1; i < 7; i++) {
      next[i] = state[i - 1] === state[i + 1] ? 1 : 0;
    }
    state = next;
    day++;
  }
  return state;
}

