function prisonAfterNDays(cells, n) {
  // From day 1 on the row repeats every 14 days (true for all 256 starting rows), so at most 14 days are simulated.
  let days = n > 14 ? ((n - 1) % 14) + 1 : n;
  let row = [...cells];
  while (days-- > 0) row = row.map((_, i) => (i > 0 && i < 7 && row[i - 1] === row[i + 1] ? 1 : 0));
  return row;
}

