function generate(rand, size) {
  const cells = Array.from({ length: 8 }, () => (rand() < 0.5 ? 1 : 0));
  if (size === 'large') return [cells, 1e9 - Math.floor(rand() * 1e6)];
  const n = rand() < 0.7 ? 1 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 1e9);
  return [cells, n];
}
